actions.script:
const out = ec.service.sync().name('mantle.marketing.ContactListServices.find#ContactLists').parameters({contactListTypeEnumId: 'MAILBOX',
    searchText: searchText || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {contactListList: out.contactListList})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.join#ContactList').parameter('contactListId', contactListId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success',
    message: ec.l10n.localize(out.statusId === 'CLPT_PENDING' ? 'Asked to join: an owner will answer' : 'Joined')}]})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.set#ContactListPartyDelivery').parameters({contactListId: contactListId || '',
    deliveryEnumId: deliveryEnumId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {effectiveDeliveryEnumId: out.effectiveDeliveryEnumId})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.add#ContactListParty').parameters({contactListId: contactListId || '',
    partyId: partyId || '', roleTypeId: roleTypeId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId})
